let connectedChannels=[],pendingPost=null,publishRequestId=null,pendingFile=null,uploadedFile=null,uploadedMedia=null,cloudReady=false;
async function api(path,payload){const response=await fetch('/api/'+path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const value=await response.json();if(!response.ok)throw Error(value.error||'The request failed.');return value;}
const setup=document.createElement('section');setup.className='panel help';setup.innerHTML=`<h2>Connect your Buffer account</h2><ol class="setup-steps"><li><a href="https://buffer.com" target="_blank" rel="noreferrer">Create or sign in to Buffer ↗</a>, then add your Instagram creator account, Facebook Page, TikTok, and X.</li><li>In Buffer, open <a href="https://publish.buffer.com/settings/api" target="_blank" rel="noreferrer">Settings → API ↗</a> and create a personal API key.</li><li>Paste the key below to load your accounts. It stays in this local server's memory until disconnect or restart; it is not saved to a file.</li></ol><p>Buffer's free plan supports up to three channels. All four require a plan that supports four channels. Review the <a href="https://buffer.com/pricing" target="_blank" rel="noreferrer">current plans</a> before choosing.</p><form id="connect-form"><label class="field-label" for="buffer-key">Buffer API key</label><input id="buffer-key" type="password" autocomplete="off" spellcheck="false" required placeholder="Paste your key here, not in chat"><div class="connection-actions"><button class="primary" type="submit">Connect Buffer</button><button type="button" class="subtle" id="refresh-accounts">Refresh accounts</button><button type="button" class="subtle" id="disconnect-buffer">Disconnect</button></div></form><p id="connection-status" role="status">Not connected</p><small>This key can access your Buffer account's organizations and channels. Only enter it on your own local Connectors page.</small>`;
$('#accounts .heading').after(setup);$('#accounts .help:last-child').remove();
const publishPanel=document.createElement('section');publishPanel.className='panel help';publishPanel.innerHTML=`<h2>Publish through Buffer</h2><p>Select the accounts to publish to below. The channel choices above are for saved drafts only.</p><div id="publish-accounts" class="channels"></div><label class="field-label" for="public-media">Public media URL <span>(optional for Facebook and X text posts)</span></label><input id="public-media" type="url" placeholder="https://your-media-host.com/photo.jpg"><label class="field-label" for="media-type">Media type</label><select id="media-type"><option value="image">Photo</option><option value="video">Video</option></select><p class="preview-disclaimer">Select a photo or video above. On confirmation it uploads to your Cloudinary account and is sent to Buffer. You can also use an existing public media URL.</p><div class="connection-actions"><button type="button" class="primary" id="review-post">Review & publish</button></div><p id="publish-error" role="status"></p>`;
$('#post-form').append(publishPanel);
const receiptsPanel=document.createElement('div');receiptsPanel.id='receipts';$('#status .heading').after(receiptsPanel);
const dialog=document.createElement('dialog');dialog.id='publish-dialog';dialog.innerHTML=`<h2>Review your real post</h2><p>This sends the following content to the selected social accounts through Buffer.</p><div id="review-summary"></div><div class="connection-actions"><button class="primary" id="confirm-publish">Publish now</button><button class="subtle" id="cancel-publish">Cancel</button></div>`;document.body.append(dialog);
$('#cancel-publish').onclick=()=>dialog.close();
function displayState(state){connectedChannels=state.channels||[];$('#connection-status').textContent=state.connected?`Buffer connected · ${connectedChannels.length} supported account(s) found`:'Not connected';$('.notice').textContent=state.connected?'Buffer connected. Save draft keeps content local; Review & publish sends it to your selected accounts.':'Connect Buffer in Connected accounts to publish. Drafts remain local until you submit them.';document.querySelector('header .badge').textContent=state.connected?'BUFFER CONNECTED':'SETUP REQUIRED';
 $('#account-grid').replaceChildren();$('#publish-accounts').replaceChildren();
 networks.forEach(n=>{const matches=connectedChannels.filter(c=>c.service===(n.id==='x'?'twitter':n.id));const card=document.createElement('article');card.className='panel account-card';const h=document.createElement('h2');h.textContent=n.icon+' '+n.name;card.append(h);if(!matches.length){const p=document.createElement('p');p.textContent='Not connected — add this account in Buffer, then refresh.';card.append(p);}for(const c of matches){const p=document.createElement('p');p.textContent=c.name+' · '+c.organization+' · '+(c.isDisconnected||c.isLocked||c.isQueuePaused?'Needs attention in Buffer':'Connected');card.append(p);const label=document.createElement('label');label.className='channel';const check=document.createElement('input');check.type='checkbox';check.value=c.id;check.disabled=!!(c.isDisconnected||c.isLocked||c.isQueuePaused);label.append(check,document.createTextNode(n.name+': '+c.name));$('#publish-accounts').append(label);}$('#account-grid').append(card);});
 if(!connectedChannels.length)$('#publish-accounts').textContent='No connected accounts yet. Open Connected accounts to set up Buffer.';
 if(state.receipts)renderReceipts(state.receipts);
}
function renderReceipts(receipts){$('#receipts').replaceChildren();for(const receipt of receipts){const card=document.createElement('article');card.className='panel draft';const h=document.createElement('h2');h.textContent='Submission · '+new Date(receipt.created).toLocaleString();card.append(h);for(const result of receipt.results){const p=document.createElement('p');p.textContent=result.name+' — '+result.status+': '+(result.message||'Not yet sent')+(result.postId?' · Buffer post '+result.postId:'');card.append(p);}const link=document.createElement('a');link.href='https://publish.buffer.com';link.target='_blank';link.rel='noreferrer';link.textContent='Verify delivery in Buffer ↗';card.append(link);$('#receipts').append(card);}}
$('#connect-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('#connection-status').textContent='Checking your Buffer account…';try{const state=await api('connect',{key:$('#buffer-key').value.trim()});$('#buffer-key').value='';displayState(state);toast('Buffer connected. Choose your accounts in Create post.');}catch(e){$('#connection-status').textContent=e.message;}finally{button.disabled=false;}};
$('#refresh-accounts').onclick=async()=>{try{displayState(await api('refresh',{}));}catch(e){$('#connection-status').textContent=e.message;}};
$('#disconnect-buffer').onclick=async()=>{try{displayState(await api('disconnect',{}));$('#buffer-key').value='';}catch(e){toast(e.message);}};
$('#review-post').onclick=()=>{try{const selected=[...document.querySelectorAll('#publish-accounts input:checked')].map(x=>x.value);if(!selected.length)throw Error(connectedChannels.length?'Select Instagram or TikTok in the Publish through Buffer section below. Draft channel choices do not select publishing accounts.':'Connect Buffer in Connected accounts first.');if(mediaFile&&!cloudReady)throw Error('Set up Cloudinary in Connected accounts to upload this file directly.');pendingFile=mediaFile;const url=$('#public-media').value.trim();if(selected.some(id=>['instagram','tiktok'].includes(connectedChannels.find(c=>c.id===id).service))&&!url&&!pendingFile)throw Error('Add a photo or video for Instagram and TikTok.');pendingPost={channelIds:selected,text:$('#caption').value,overrides:{...overrides},date:$('#date').value?new Date($('#date').value).toISOString():undefined,media:url?{url,type:$('#media-type').value}:undefined};if(!pendingPost.text.trim()&&!url&&!pendingFile&&!Object.values(overrides).some(x=>x.trim()))throw Error('Add content first.');if(pendingPost.date&&new Date(pendingPost.date)<=new Date())throw Error('Choose a future date.');$('#review-summary').replaceChildren();for(const id of selected){const c=connectedChannels.find(c=>c.id===id);const p=document.createElement('p');p.textContent=c.service+' · '+c.name+'\n'+(overrides[c.service==='twitter'?'x':c.service]||pendingPost.text);$('#review-summary').append(p);}const media=document.createElement('p');media.textContent=pendingFile?'File: '+pendingFile.name+' — will upload to Cloudinary as publicly accessible media when you confirm.':url?'Media: '+url:'Text only';$('#review-summary').append(media);const when=document.createElement('p');when.textContent=pendingPost.date?'Scheduled: '+new Date(pendingPost.date).toLocaleString():'Publish now';$('#review-summary').append(when);$('#confirm-publish').textContent=pendingPost.date?'Schedule post':'Publish now';publishRequestId=crypto.randomUUID();$('#publish-error').textContent='';dialog.showModal();}catch(e){$('#publish-error').textContent=e.message;}};
$('#confirm-publish').onclick=async()=>{const button=$('#confirm-publish');button.disabled=true;$('#cancel-publish').disabled=true;button.textContent='Submitting…';try{if(pendingFile){button.textContent='Uploading media…';pendingPost.media=await uploadSelectedFile(pendingFile);button.textContent='Publishing…';}const data=await api('publish',{...pendingPost,requestId:publishRequestId});dialog.close();go('status');renderReceipts((await api('status')).receipts);toast(data.duplicate?'This content was submitted before. Showing its existing result.':'Submission finished. Check each channel’s result and verify delivery in Buffer.');}catch(e){dialog.close();$('#publish-error').textContent=e.message;toast('Submission not confirmed. Check Publishing status and Buffer before retrying.');try{renderReceipts((await api('status')).receipts);}catch{}}finally{button.disabled=false;$('#cancel-publish').disabled=false;button.textContent='Publish now';}};
preview();
api('status').then(state=>{displayState(state);if(!state.connected)go('accounts');}).catch(e=>toast('Connection service unavailable: '+e.message));

const cloudPanel=document.createElement('section');cloudPanel.className='panel help';cloudPanel.innerHTML='<h2>Media uploads · Cloudinary</h2><p>In your Cloudinary console, open Settings → API Keys. Enter your cloud name, API key, and API secret here. Credentials stay in this local server’s memory until restart or disconnect.</p><form id="cloud-form"><label class="field-label" for="cloud-name">Cloud name</label><input id="cloud-name" required autocomplete="off"><label class="field-label" for="cloud-key">API key</label><input id="cloud-key" type="password" required autocomplete="off"><label class="field-label" for="cloud-secret">API secret</label><input id="cloud-secret" type="password" required autocomplete="off"><div class="connection-actions"><button class="primary" type="submit">Enable media uploads</button><button type="button" class="subtle" id="cloud-disconnect">Disconnect media storage</button></div></form><p id="cloud-status" role="status">Not configured</p>';setup.after(cloudPanel);
function cloudState(state){cloudReady=!!state.configured;$('#cloud-status').textContent=cloudReady?'Configured for '+state.cloud+'. Credentials will be verified on your first upload.':'Not configured';}
$('#cloud-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{cloudState(await api('cloudinary/connect',{cloud:$('#cloud-name').value,key:$('#cloud-key').value,secret:$('#cloud-secret').value}));$('#cloud-key').value='';$('#cloud-secret').value='';toast('Media storage configured. Select your file in Create post.');}catch(e){$('#cloud-status').textContent=e.message;}finally{button.disabled=false;}};
$('#cloud-disconnect').onclick=async()=>{try{cloudState(await api('cloudinary/disconnect',{}));uploadedFile=null;uploadedMedia=null;}catch(e){toast(e.message);}};
api('status').then(s=>cloudState(s.cloudinary||{})).catch(()=>{});
async function uploadSelectedFile(file){
 if(file===uploadedFile&&uploadedMedia)return uploadedMedia;
 const signed=await api('cloudinary/sign',{type:file.type,size:file.size});const data=new FormData();data.append('file',file);for(const key of ['api_key','timestamp','signature'])data.append(key,String(signed[key]));
 let response;try{response=await fetch(signed.endpoint,{method:'POST',body:data,signal:AbortSignal.timeout(180000)});}catch{throw Error('Media upload did not finish. No new publish request was made. Check your internet connection and Cloudinary media library.');}
 const result=await response.json();if(!response.ok||!result.secure_url)throw Error(result.error?.message||'Cloudinary could not upload this file. Check your credentials.');
 if(!result.secure_url.startsWith('https://res.cloudinary.com/'))throw Error('Unexpected media delivery URL. Publishing stopped.');
 uploadedFile=file;uploadedMedia={url:result.secure_url,type:file.type.startsWith('video/')?'video':'image'};return uploadedMedia;
}
